// Base64 encoded fonts for reliable @react-pdf/renderer compatibility
// TTF format is most reliable; woff2 has known issues with the PDF renderer
// See: https://github.com/diegomura/react-pdf/issues/2223

import { Font } from '@react-pdf/renderer'


export const GEIST_REGULAR_BASE64 = 'data:font/truetype;base64,'

export const GEIST_BOLD_BASE64 = 'data:font/truetype;base64,'

export const GEIST_MONO_REGULAR_BASE64 = 'data:font/truetype;base64,'

export const GEIST_MONO_BOLD_BASE64 = 'data:font/truetype;base64,'

let fontsRegistered = false

export function ensureFontsRegistered() {
  if (fontsRegistered) return
  fontsRegistered = true

  Font.register({
    family: 'Geist',
    fonts: [
      { src: GEIST_REGULAR_BASE64, fontWeight: 'normal' },
      { src: GEIST_BOLD_BASE64, fontWeight: 'bold' },
    ],
  })

  Font.register({
    family: 'Geist Mono',
    fonts: [
      { src: GEIST_MONO_REGULAR_BASE64, fontWeight: 'normal' },
      { src: GEIST_MONO_BOLD_BASE64, fontWeight: 'bold' },
    ],
  })
}
